def fig_pt():
    X=lambda t:50+t*2.7;Y=lambda r:190-(r-100)*(160/38.5)
    o=L(50,190,330,190)+L(50,20,50,190)+f'<line x1="{X(0)}" y1="{Y(100):.1f}" x2="{X(100)}" y2="{Y(138.5):.1f}" class="lna"/>'
    o+=L(50,Y(138.5),X(100),Y(138.5),'ln dash')+L(X(100),Y(138.5),X(100),190,'ln dash')+C(X(100),Y(138.5),4,'hda')
    for r in (100,138.5):o+=TR(46,Y(r)+4,str(r).replace('.',','),'t-s')
    for t in (0,50,100):o+=T(X(t),205,str(t),'t-s')
    o+=TL(58,26,'R, Ом','t-s t-b')+TL(250,198,'T, °C','t-s t-b').replace('y="198"','y="218"')+TL(X(100)-130,Y(138.5)+24,'138,5 Ом → 100 °C','t-s ac')
    return S(340,226,o,'Pt100 термокедергісінің кедергісінің температураға тәуелділігі')
f_pt=F(fig_pt(),'Pt100: 0 °C-та 100 Ом, әр градусқа ≈ 0,385 Ом (α = 0,00385). Ғимарат температураларында сызық дерлік түзу')

