def fig_q():
    X=lambda d:50+d*(270/16);Y=lambda q:190-q*160
    pts=[(d/4,math.sqrt(d/4/16)) for d in range(0,65)]
    o=L(50,190,330,190)+L(50,20,50,190)+'<path d="M'+' L'.join(f'{X(d):.1f} {Y(q):.1f}' for d,q in pts)+'" class="lna"/>'
    for d,q in ((4,0.5),(16,1.0)):o+=L(50,Y(q),X(d),Y(q),'ln dash')+L(X(d),Y(q),X(d),190,'ln dash')+C(X(d),Y(q),4,'hda')
    for q,t in ((0.5,'50 %'),(1.0,'100 %')):o+=TR(46,Y(q)+4,t,'t-s')
    for d in (0,4,8,12,16):o+=T(X(d),205,str(d),'t-s')
    o+=TL(58,26,'шығын Q','t-s t-b')+TL(240,218,'Δp, кПа','t-s t-b')+TL(X(4)+8,Y(0.5)+18,'Δp 4 есе → Q 2 есе','t-s ac')
    return S(340,226,o,'Тарылтқыш құрылғыдағы шығынның қысым айырмасына тәуелділігі')
f_q=F(fig_q(),'Дифференциалды қысым әдісі: Q ∼ √Δp. Δp 4-тен 16 кПа-ға (4 есе) өссе, шығын 2 есе ғана өседі (сандар — мысал үшін)')

def fig_step():
    X=lambda t:50+t*54;Y=lambda y:190-y*160
    pts=[(k/20,1-math.exp(-k/20)) for k in range(0,101)]
    o=L(50,190,330,190)+L(50,20,50,190)+L(50,Y(1),330,Y(1),'ln dash')+'<path d="M'+' L'.join(f'{X(t):.1f} {Y(y):.1f}' for t,y in pts)+'" class="lna"/>'
    for t,y in ((1,0.632),(3,0.950)):o+=L(X(t),Y(y),X(t),190,'ln dash')+C(X(t),Y(y),4,'hda')
    o+=T(X(1),205,'τ','t-s')+T(X(3),205,'3τ','t-s')+TR(46,Y(1)+4,'100 %','t-s')+TL(X(1)+8,Y(0.632)+16,'63 %','t-s ac')+TL(X(3)-14,Y(0.95)-24,'95 %','t-s ac')
    o+=TL(58,26,'көрсеткіш','t-s t-b')+TL(260,218,'уақыт','t-s t-b')
    return S(340,226,o,'Датчиктің қадамдық өзгеріске жауабы: уақыт тұрақтысы')
f_step=F(fig_step(),'Температура секіріп өзгергенде датчик көрсеткіші бірден емес, экспонента бойынша жетеді: τ уақытында 63 %, 3τ уақытында 95 %')

